//! Slice 2: purge execution and obligation reports (v2 sha256
//! `b55bf6b2…8456`). Fixtures are generated by `testkit` with published
//! test keys. Cases the official goldens cover (V1–V5, V10, V11's
//! acceptance at D, V13's list) run in `golden`; these are the rest.

use super::*;
use crate::canonical::sha256_tagged;
use crate::holder::ListOutcome;
use crate::obligations::{Pending, PendingStatus, PurgeStep, Uncertain};
use crate::purge::ObligationsRefused;
use crate::state::{STATE_FILE, WriteError};
use crate::store::ResourceKey;
use crate::testkit::{FakeReserve, Fault, Forced, PurgerUnit, TEST_ISSUER};
use crate::wire::ReportState;
use serde_json::{Map, Value, json};
use std::collections::BTreeSet;

const A: &str = "resAAAAAAAAAAAAAAAAAAAAA";
const B: &str = "resBBBBBBBBBBBBBBBBBBBBB";
const C: &str = "resCCCCCCCCCCCCCCCCCCCCC";
const X: &str = "resXXXXXXXXXXXXXXXXXXXXX";

struct World {
    _dir: tempfile::TempDir,
    rig: Rig,
    b_holding: String,
    b_obligation: String,
}

/// A held and listed `active` (2 units), B held and `terminating` (3
/// units), and with `unknown`, X held but never listed (1 unit).
fn world(unknown: bool) -> World {
    let (dir, mut rig) = rig();
    rig.store.hold(PLAIN, A, true, 2);
    rig.store.hold(PLAIN, B, true, 3);
    rig.purger.add(PLAIN, A, 2);
    rig.purger.add(PLAIN, B, 3);
    if unknown {
        rig.store.hold(PLAIN, X, true, 1);
        rig.purger.add(PLAIN, X, 1);
    }
    let (b_holding, b_obligation) = {
        let mut authority = rig.authority.state();
        authority.add_active(PLAIN, A);
        let holding = authority.add_active(PLAIN, B);
        let obligation = authority.retire(&holding);
        (holding, obligation)
    };
    applied(rig.relist());
    World {
        _dir: dir,
        rig,
        b_holding,
        b_obligation,
    }
}

fn key(id: &str) -> ResourceKey {
    ResourceKey {
        kind: PLAIN.into(),
        id: id.into(),
    }
}

fn units_of(rig: &Rig, id: &str) -> Vec<String> {
    let key = key(id);
    rig.purger
        .view()
        .units
        .iter()
        .filter(|(_, u)| u.attribution.as_ref() == Some(&key))
        .map(|(unit, _)| unit.clone())
        .collect()
}

/// Claims of every report the authority accepted, in order.
fn accepted(rig: &Rig) -> Vec<Map<String, Value>> {
    rig.authority
        .state()
        .reports
        .iter()
        .filter(|(_, status)| *status == 200)
        .map(|(claims, _)| claims.clone())
        .collect()
}

fn accepted_states(rig: &Rig) -> Vec<String> {
    accepted(rig)
        .iter()
        .map(|c| c["state"].as_str().unwrap().to_owned())
        .collect()
}

fn floor(rig: &mut Rig, obligation: &str) -> Option<ReportState> {
    let epoch = rig.holder().state().high_water.clone()?.epoch;
    rig.holder()
        .state()
        .obligations
        .channels
        .get(obligation)
        .and_then(|c| c.floor_in(&epoch))
}

fn pending(rig: &mut Rig, obligation: &str) -> Option<Pending> {
    rig.holder()
        .state()
        .obligations
        .channels
        .get(obligation)
        .and_then(|c| c.pending.clone())
}

fn holder_files(rig: &Rig, prefix: &str) -> Vec<String> {
    std::fs::read_dir(&rig.dir)
        .unwrap()
        .filter_map(|e| e.ok()?.file_name().into_string().ok())
        .filter(|name| name.starts_with(prefix))
        .collect()
}

fn forced(rig: &Rig, response: crate::client::HttpResponse) {
    rig.authority
        .state()
        .forced
        .push_back(Forced::Response(response));
}

fn problem(rig: &Rig, status: u16, code: &str, current_ack: Option<String>) {
    let response = rig
        .authority
        .state()
        .problem_answer(status, code, current_ack);
    forced(rig, response);
}

/// An ack a correct authority signs, with chosen claims.
fn forged_ack(
    rig: &Rig,
    (obligation_id, holding_id): (&str, &str),
    accepted: &str,
    obligation_state: &str,
    phase: &str,
    epoch: &str,
) -> String {
    let state = rig.authority.state();
    let claims = json!({
        "iss": TEST_ISSUER,
        "aud": state.config.profile.holder_audience(&state.holder_id),
        "sub": state.holder_id,
        "iat": state.now_ms().div_euclid(1000),
        "jti": "ak_FORGEDforged000000000001",
        "idempotency_key": "ik_anotherHoldersKey0000000000000000000000000",
        "report_jti": "jtiJTIjtiJTIjtiJTIjtiJ",
        "report_digest": sha256_tagged(b"another report"),
        "obligation_id": obligation_id,
        "holding_id": holding_id,
        "accepted_state": accepted,
        "obligation_state": obligation_state,
        "phase": phase,
        "rev": { "epoch": epoch, "seq": 1 },
        "receipt_label": "confirmed",
    });
    state.sign_ack(&claims)
}

// ------------------------------------------------------------------ H1, H2

#[test]
fn h1_h2_reports_follow_the_purge_and_never_complete_over_unattributed_data() {
    let mut w = world(true);
    let rig = &mut w.rig;
    assert_eq!(plain(rig, A), Ok(()));
    assert!(plain(rig, B).is_err());

    let summary = rig.report().unwrap();
    assert_eq!((summary.derived, summary.sent, summary.receipts), (1, 1, 1));
    assert_eq!(floor(rig, &w.b_obligation), Some(ReportState::Revoked));

    let purged = rig.purge().unwrap();
    assert_eq!((purged.deleted, purged.verified), (3, 1));
    assert_eq!(rig.report().unwrap().receipts, 1);
    // A second pass changes nothing and sends nothing.
    rig.purge().unwrap();
    assert_eq!(rig.report().unwrap().sent, 0);
    assert_eq!(accepted_states(rig), ["revoked", "incomplete"]);
    let incomplete = accepted(rig).pop().unwrap();
    assert_eq!(
        incomplete["counts"],
        json!({"units_purged": 3, "units_remaining": 0, "quarantined_unattributed": 1})
    );
    // X is quarantined, never deleted; A untouched.
    assert_eq!(rig.purger.present_of(PLAIN, X), 1);
    assert_eq!(rig.purger.present_of(PLAIN, A), 2);
    assert!(rig.store.bytes_present(PLAIN, X));

    // H2 (S2 form): once X is attributed, B completes.
    rig.authority.state().add_active(PLAIN, X);
    applied(rig.relist());
    rig.purge().unwrap();
    assert_eq!(rig.report().unwrap().receipts, 1);
    let complete = accepted(rig).pop().unwrap();
    assert_eq!(complete["state"], "complete");
    assert_eq!(
        complete["counts"],
        json!({"units_purged": 3, "units_remaining": 0, "quarantined_unattributed": 0})
    );
    assert_eq!(complete["method"], "logical_delete");
    assert_eq!(complete["evidence"]["kind"], "witness-digest/v2");
    // The evidence digest is the SHA-256 of the stored final-scan record.
    let key = complete["idempotency_key"].as_str().unwrap();
    let record = std::fs::read(rig.dir.join(format!("scan.{key}.json"))).unwrap();
    assert_eq!(complete["evidence"]["digest"], sha256_tagged(&record));
    assert!(!String::from_utf8(record).unwrap().contains(B));
    assert_eq!(
        rig.authority.state().obligation_state(&w.b_holding),
        "complete"
    );
    assert_eq!(floor(rig, &w.b_obligation), Some(ReportState::Complete));
    assert_eq!(rig.purger.present_of(PLAIN, A), 2);
    assert_eq!(rig.purger.present_of(PLAIN, X), 1);
}

#[test]
fn h16_a_report_carries_only_its_own_obligation_and_no_resource_id() {
    let mut w = world(true);
    let rig = &mut w.rig;
    rig.report().unwrap();
    rig.purge().unwrap();
    rig.report().unwrap();
    let allowed: BTreeSet<&str> = [
        "iss",
        "sub",
        "aud",
        "htu",
        "iat",
        "exp",
        "jti",
        "idempotency_key",
        "obligation_id",
        "holding_id",
        "state",
        "list_ref",
        "counts",
        "quarantine_manifest_digest",
        "method",
        "completed_at",
        "evidence",
        "operator",
    ]
    .into();
    let reports = accepted(rig);
    assert_eq!(reports.len(), 2);
    for claims in reports {
        assert!(claims.keys().all(|k| allowed.contains(k.as_str())));
        assert_eq!(claims["obligation_id"], w.b_obligation.as_str());
        assert_eq!(
            claims["exp"].as_i64().unwrap() - claims["iat"].as_i64().unwrap(),
            300
        );
        let text = Value::Object(claims).to_string();
        for id in [A, B, X] {
            assert!(!text.contains(id), "resource id in a report");
        }
    }
}

// ------------------------------------------------- deletion authority (§3.4)

#[test]
fn nothing_is_deleted_without_a_listed_obligation_and_its_exact_claimant() {
    let mut w = world(true);
    let rig = &mut w.rig;
    let stray = rig.purger.add_unattributable();
    for unit in units_of(rig, B) {
        rig.purger.view().units.get_mut(&unit).unwrap().open_handles = 1;
    }
    let first = rig.purge().unwrap();
    assert_eq!((first.deleted, first.waiting_on_handles), (0, 3));

    // Lease expiry with the authority unreachable deletes nothing.
    rig.authority.state().forced.push_back(Forced::Unreachable);
    rig.advance(1_000_000);
    failed(rig.holder().list_once());
    assert_eq!(plain(rig, A), Err(Refusal::LeaseLapsed));
    assert_eq!(rig.purge(), Err(ObligationsRefused::NoCurrentAuthority));

    // B leaves the list: absence alone authorizes nothing, and its data
    // becomes unattributed quarantine.
    rig.authority.state().remove(&w.b_holding);
    applied(rig.relist());
    for unit in units_of(rig, B) {
        rig.purger.view().units.get_mut(&unit).unwrap().open_handles = 0;
    }
    assert_eq!(rig.purge().unwrap().deleted, 0);
    assert!(rig.holder().state().obligations.channels.is_empty());

    let view = rig.purger.view();
    assert!(view.deletions.is_empty());
    assert!(view.refused.is_empty(), "{:?}", view.refused);
    assert!(view.units.values().all(|u| u.present));
    assert!(view.units[&stray].present);
}

#[test]
fn open_handles_and_unlinked_open_files_block_complete() {
    let mut w = world(false);
    let rig = &mut w.rig;
    let b_units = units_of(rig, B);
    rig.purger
        .view()
        .units
        .get_mut(&b_units[0])
        .unwrap()
        .open_handles = 1;
    rig.report().unwrap();
    let pass = rig.purge().unwrap();
    assert_eq!((pass.deleted, pass.waiting_on_handles), (2, 1));
    rig.report().unwrap();
    assert_eq!(accepted(rig).pop().unwrap()["counts"]["units_remaining"], 1);

    // Unlinked, but a descriptor still holds it: the census still sees it.
    rig.purger
        .view()
        .units
        .get_mut(&b_units[0])
        .unwrap()
        .present = false;
    rig.purge().unwrap();
    rig.report().unwrap();
    assert!(!accepted_states(rig).contains(&"complete".to_owned()));

    rig.purger
        .view()
        .units
        .get_mut(&b_units[0])
        .unwrap()
        .open_handles = 0;
    rig.purge().unwrap();
    rig.report().unwrap();
    assert_eq!(accepted_states(rig).last().unwrap(), "complete");
}

#[test]
fn o14x_a_late_builder_output_cancels_complete_before_its_first_byte() {
    let mut w = world(false);
    let rig = &mut w.rig;
    rig.report().unwrap();
    rig.purge().unwrap();
    {
        // Published after the guard's census, before the first byte.
        let mut view = rig.purger.view();
        let at = view.census_calls + 2;
        view.late.push((
            at,
            "late0001".into(),
            PurgerUnit {
                attribution: Some(key(B)),
                open_handles: 0,
                reserved: false,
                present: true,
            },
        ));
    }
    let posts = rig.authority.state().posts();
    let summary = rig.report().unwrap();
    assert_eq!((summary.cancelled, summary.sent), (1, 0));
    assert_eq!(rig.authority.state().posts(), posts, "never transmitted");
    let report = pending(rig, &w.b_obligation).unwrap();
    assert_eq!(report.status, PendingStatus::Invalidated);
    assert!(report.attempts.is_empty());
    assert!(rig.holder().state().obligations.uncertain.is_empty());
    assert!(holder_files(rig, "sent.").is_empty());

    // The late unit is purged under the obligation, then complete is sent.
    rig.purge().unwrap();
    rig.report().unwrap();
    assert_eq!(accepted_states(rig), ["revoked", "complete"]);
    assert!(
        rig.purger
            .view()
            .deletions
            .contains(&("late0001".into(), w.b_obligation.clone()))
    );
}

#[test]
fn v13_a_blocked_obligation_is_purged_as_terminating_and_authorizes_nothing_else() {
    let mut w = world(true);
    let rig = &mut w.rig;
    rig.report().unwrap();
    rig.purge().unwrap();
    rig.report().unwrap();
    rig.authority
        .state()
        .set_obligation_state(&w.b_holding, "blocked");
    applied(rig.relist());
    assert!(plain(rig, B).is_err());
    rig.purger.add(PLAIN, B, 1);
    rig.purge().unwrap();
    assert_eq!(rig.purger.present_of(PLAIN, B), 0);
    assert_eq!(rig.purger.present_of(PLAIN, X), 1);
    assert!(
        rig.purger
            .view()
            .deletions
            .iter()
            .all(|(_, ob)| *ob == w.b_obligation)
    );
    rig.report().unwrap();
    assert_eq!(
        accepted_states(rig),
        ["revoked", "incomplete", "incomplete"]
    );
}

#[test]
fn v5_residual_data_of_a_retired_complete_holding_is_purged_and_reconfirmed() {
    let mut w = world(false);
    let rig = &mut w.rig;
    rig.report().unwrap();
    rig.purge().unwrap();
    rig.report().unwrap();
    assert_eq!(accepted_states(rig), ["revoked", "complete"]);
    applied(rig.relist());
    // §3.4 rule 4: data reappeared after `complete`.
    let residual = rig.purger.add(PLAIN, B, 2);
    rig.purge().unwrap();
    assert!(residual.iter().all(|u| !rig.purger.present(u)));
    let summary = rig.report().unwrap();
    assert_eq!((summary.sent, summary.converged), (1, 1));
    // V5: a convergence receipt, never a receipt for the sent key.
    assert!(codes(rig).contains(&"lifecycle_report_converged"));
    assert_eq!(holder_files(rig, "conv.").len(), 1);
    assert_eq!(holder_files(rig, "receipt.").len(), 2);
    assert!(pending(rig, &w.b_obligation).is_none());
    assert_eq!(floor(rig, &w.b_obligation), Some(ReportState::Complete));
    // Reconfirmed once; nothing repeats.
    rig.advance(400_000);
    applied(rig.relist());
    rig.purge().unwrap();
    assert_eq!(rig.report().unwrap().sent, 0);
}

// ----------------------------------------------------------- V1–V4, H10

#[test]
fn h5_a_current_epoch_state_regression_converges_the_floor() {
    let mut w = world(true);
    let rig = &mut w.rig;
    rig.report().unwrap();
    rig.purge().unwrap();
    let epoch = rig.holder().state().high_water.clone().unwrap().epoch;
    let current = forged_ack(
        rig,
        (&w.b_obligation, &w.b_holding),
        "complete",
        "complete",
        "retired",
        &epoch,
    );
    problem(rig, 409, "state_regression", Some(current));
    assert_eq!(rig.report().unwrap().converged, 1);
    assert_eq!(floor(rig, &w.b_obligation), Some(ReportState::Complete));
    assert!(pending(rig, &w.b_obligation).is_none());
    // A convergence ack is stored as such, never as a receipt for the key.
    assert_eq!(holder_files(rig, "conv.").len(), 1);
    assert_eq!(holder_files(rig, "receipt.").len(), 1);
}

// ------------------------------------------------------- V10, V11, errors

#[test]
fn v11_a_commit_after_the_proof_deadline_commits_nothing_and_is_re_signed_once() {
    let mut w = world(false);
    let rig = &mut w.rig;
    let posts = rig.authority.state().posts();
    let seq = rig.authority.state().seq;
    {
        let mut authority = rig.authority.state();
        authority.before_post(posts + 1, |s| s.commit_delay_ms = 421_000);
        authority.before_post(posts + 2, |s| s.commit_delay_ms = 0);
    }
    let summary = rig.report().unwrap();
    assert_eq!((summary.sent, summary.receipts), (2, 1));
    let state = rig.authority.state();
    let statuses: Vec<u16> = state.reports.iter().map(|(_, s)| *s).collect();
    assert_eq!(statuses, [401, 200]);
    // The refused attempt committed nothing: one transaction only.
    assert_eq!(state.seq, seq + 1);
    assert_eq!(state.report_receipts.len(), 1);
}

#[test]
fn r7_stale_list_ref_relists_then_re_derives_under_a_new_key() {
    let mut w = world(false);
    let rig = &mut w.rig;
    problem(rig, 409, "stale_list_ref", None);
    let summary = rig.report().unwrap();
    assert_eq!(summary.rejected, 1);
    let rejected = pending(rig, &w.b_obligation).unwrap();
    assert_eq!(rejected.status, PendingStatus::Rejected);
    assert!(rejected.attempts.is_empty(), "definitively not accepted");
    assert_eq!(rig.report().unwrap().derived, 0, "relist first");
    applied(rig.relist());
    assert_eq!(rig.report().unwrap().receipts, 1);
    let sent = accepted(rig).pop().unwrap();
    assert_ne!(sent["idempotency_key"], rejected.key.as_str());
    assert_eq!(sent["state"], "revoked");
}

#[test]
fn r9_r17_bug_answers_halt_the_channel_durably() {
    let mut w = world(false);
    let rig = &mut w.rig;
    problem(rig, 400, "invalid_request", None);
    assert_eq!(rig.report().unwrap().halted, 1);
    assert!(codes(rig).contains(&"lifecycle_report_bug_halt"));
    rig.restart().unwrap();
    applied(rig.relist());
    rig.advance(20_000);
    let summary = rig.report().unwrap();
    assert_eq!((summary.derived, summary.sent), (0, 0));

    // Three unverifiable acks in a row also halt.
    let mut w = world(false);
    let rig = &mut w.rig;
    for _ in 0..3 {
        let junk = rig.authority.state().ack_answer("not.a.jws", None);
        forced(rig, junk);
        rig.advance(1_000);
        rig.report().unwrap();
    }
    assert!(rig.holder().state().obligations.channels[&w.b_obligation].halted);
}

#[test]
fn r11r_replay_is_retried_once_with_a_fresh_jti() {
    let mut w = world(false);
    let rig = &mut w.rig;
    problem(rig, 401, "replay", None);
    let summary = rig.report().unwrap();
    assert_eq!((summary.sent, summary.receipts), (2, 1));
    assert_eq!(
        rig.holder().route_health(),
        crate::holder::RouteHealth::Normal
    );
}

// --------------------------------------------------------------- M10, H.22

#[test]
fn m10_a_403_cancels_queued_unsent_reports_and_keeps_possibly_sent_ones_uncertain() {
    let mut w = world(false);
    let rig = &mut w.rig;
    // B: sent, its ack lost, so it may have been accepted.
    rig.authority.state().drop_acks = 1;
    assert_eq!(rig.report().unwrap().sent, 1);
    let b_key = pending(rig, &w.b_obligation).unwrap().key;
    // C: derived and queued, held back by the status-first gate.
    rig.store.hold(PLAIN, C, true, 1);
    rig.purger.add(PLAIN, C, 1);
    let c_obligation = {
        let mut authority = rig.authority.state();
        let holding = authority.add_active(PLAIN, C);
        authority.retire(&holding)
    };
    applied(rig.relist());
    let epoch = rig.holder().state().high_water.clone().unwrap().epoch;
    rig.holder().arm_status_gate(&epoch);
    // B's retry (already sent while the gate was open) is lost again.
    rig.authority.state().drop_acks = 1;
    rig.report().unwrap();
    assert_eq!(pending(rig, &w.b_obligation).unwrap().key, b_key);
    let queued = pending(rig, &c_obligation).unwrap();
    assert!(queued.attempts.is_empty() && queued.live());

    problem(rig, 403, "holder_not_authorized", None);
    rig.advance(400_000);
    failed(rig.holder().list_once());
    assert_eq!(plain(rig, A), Err(Refusal::AuthHalt));
    assert!(codes(rig).contains(&"lifecycle_reports_cancelled"));
    let book = rig.holder().state().obligations.clone();
    assert!(
        book.channels[&c_obligation].pending.is_none(),
        "cancelled unsent"
    );
    let b = book.channels[&w.b_obligation].pending.as_ref().unwrap();
    assert_eq!(b.status, PendingStatus::Invalidated);
    assert!(
        book.uncertain.contains_key(&b_key),
        "possibly sent: uncertain"
    );
    // Nothing more is sent until an operator restart.
    let posts = rig.authority.state().posts();
    rig.holder().record_status_ack(&epoch);
    rig.advance(60_000);
    assert_eq!(rig.report().unwrap().sent, 0);
    assert_eq!(rig.authority.state().posts(), posts);
}

#[test]
fn h22_h27_the_status_first_gate_holds_first_sends_and_survives_restart() {
    let mut w = world(false);
    let rig = &mut w.rig;
    let epoch = rig.holder().state().high_water.clone().unwrap().epoch;
    assert!(rig.holder().arm_status_gate(&epoch));
    let summary = rig.report().unwrap();
    assert_eq!((summary.derived, summary.sent, summary.waiting), (1, 0, 1));
    // Durable (H.27): still shut after a restart.
    rig.restart().unwrap();
    applied(rig.relist());
    assert_eq!(rig.report().unwrap().sent, 0);
    // A status bug halt releases it (H.22.3).
    assert!(rig.holder().record_status_halted(true));
    assert_eq!(rig.report().unwrap().receipts, 1);
    // An operator resume closes it again until a current-epoch status ack.
    assert!(rig.holder().record_status_halted(false));
    rig.purge().unwrap();
    assert_eq!(rig.report().unwrap().sent, 0);
    assert!(rig.holder().record_status_ack(&epoch));
    assert_eq!(rig.report().unwrap().receipts, 1);
}

// ------------------------------------------------------------ H11, H12

#[test]
fn h11_h12_after_holder_state_loss_the_list_floor_forbids_lower_states() {
    let mut w = world(true);
    let rig = &mut w.rig;
    let b_units = units_of(rig, B);
    rig.purger
        .view()
        .units
        .get_mut(&b_units[0])
        .unwrap()
        .open_handles = 1;
    rig.report().unwrap();
    rig.purge().unwrap();
    rig.report().unwrap();
    assert_eq!(accepted_states(rig), ["revoked", "incomplete"]);
    // Holder state and data root binding are both lost: trust on first use.
    std::fs::remove_file(rig.dir.join(STATE_FILE)).unwrap();
    rig.data_root.view().marker = None;
    rig.restart().unwrap();
    assert!(codes(rig).contains(&"holder_state_reset"));
    applied(rig.relist());
    assert_eq!(floor(rig, &w.b_obligation), Some(ReportState::Incomplete));
    let before = accepted(rig).len();
    rig.report().unwrap();
    rig.purge().unwrap();
    rig.report().unwrap();
    let states = accepted_states(rig);
    assert!(states[before..].iter().all(|s| s != "revoked"));
    assert_eq!(rig.purger.present_of(PLAIN, X), 1);
}

// ----------------------------------------------- crash at every durable step

fn crash_case(faults: Vec<Fault>, crash_after_deletes: Option<usize>) {
    let mut w = world(false);
    let rig = &mut w.rig;
    rig.report().unwrap();
    let b_units: BTreeSet<String> = units_of(rig, B).into_iter().collect();
    rig.io_faults.plan(faults.clone());
    rig.purger.view().crash_after_deletes = crash_after_deletes;
    let _ = rig.purge();
    // The process ends here with only what is durable.
    rig.io_faults.clear();
    rig.purger.view().crash_after_deletes = None;
    rig.restart().unwrap();
    assert_eq!(rig.purge(), Err(ObligationsRefused::NoListThisProcess));
    applied(rig.relist());
    for _ in 0..3 {
        rig.purge().unwrap();
        rig.advance(1_000);
        rig.report().unwrap();
    }
    let context = format!("{faults:?} crash_after={crash_after_deletes:?}");
    assert_eq!(rig.purger.present_of(PLAIN, B), 0, "{context}");
    assert_eq!(rig.purger.present_of(PLAIN, A), 2, "{context}");
    let view = rig.purger.view();
    assert!(view.refused.is_empty(), "{context}: {:?}", view.refused);
    assert!(
        view.deletions
            .iter()
            .all(|(unit, ob)| *ob == w.b_obligation && b_units.contains(unit)),
        "{context}"
    );
    drop(view);
    let states = accepted_states(rig);
    let ranks: Vec<_> = states
        .iter()
        .map(|s| ReportState::from_wire(s).unwrap())
        .collect();
    assert!(
        ranks.windows(2).all(|p| p[0] <= p[1]),
        "{context}: {states:?}"
    );
    assert_eq!(states.last().unwrap(), "complete", "{context}");
    assert_eq!(
        accepted(rig).pop().unwrap()["counts"]["units_purged"],
        3,
        "{context}"
    );
    assert_eq!(
        rig.holder().state().obligations.channels[&w.b_obligation]
            .purge
            .step,
        PurgeStep::Deleted
    );
}

#[test]
fn purge_crashes_at_every_durable_step_resume_without_unauthorized_deletion() {
    // One target: W(Detaching), W(Detached), W(Deleting), W(Deleted).
    for step in 0..4 {
        for fault in [Fault::BeforeRename, Fault::AfterRename] {
            let mut plan = vec![Fault::Pass; step];
            plan.push(fault);
            crash_case(plan, None);
        }
    }
    // A crash between deletions, after the claim and before W(Deleted).
    for after in 0..3 {
        crash_case(Vec::new(), Some(after));
    }
}

