#[test]
fn h45_after_a_fail_stop_no_purge_report_or_write_runs() {
    let mut w = world(false);
    let rig = &mut w.rig;
    rig.report().unwrap();
    // A one-page list, so a `page_size: 1` probe sees all of it (H.29).
    {
        let mut authority = rig.authority.state();
        let a_holding = authority
            .items
            .iter()
            .find(|(_, item)| item["resource"]["id"] == A)
            .map(|(holding, _)| holding.clone())
            .unwrap();
        authority.remove(&a_holding);
    }
    // Slice 1's unpersistable clock-hold poison: raise, then a clear whose
    // seal fsync, raised record and seal removal all fail.
    rig.authority.state().offset_ms = 45_000;
    applied(rig.relist());
    assert!(rig.engine_gate().clock_hold());
    rig.authority.state().offset_ms = 0;
    rig.io_faults
        .plan(vec![Fault::Pass, Fault::AfterRename, Fault::BeforeRename]);
    rig.io_faults.fail_removes();
    rig.advance(5_000);
    assert_eq!(
        rig.holder().probe_clock(),
        Some(Err(crate::client::FetchFailure::HolderStateUnwritable))
    );
    rig.io_faults.clear();

    let state_bytes = std::fs::read(rig.dir.join(STATE_FILE)).unwrap();
    let files = holder_files(rig, "");
    let posts = rig.authority.state().posts();
    let calls = rig.purger.view().calls.len();
    assert_eq!(rig.purge(), Err(ObligationsRefused::HolderStateUnwritable));
    assert_eq!(rig.report(), Err(ObligationsRefused::HolderStateUnwritable));
    assert!(!rig.holder().arm_status_gate("ep_SOMEepoch0000000000001"));
    let book = rig.holder().state().obligations.clone();
    assert!(matches!(
        rig.holder().writer.update_obligations(Default::default()),
        Err(WriteError::Unwritable)
    ));
    assert_eq!(rig.holder().state().obligations, book);
    assert_eq!(rig.purger.view().calls.len(), calls, "no purger call");
    assert!(rig.purger.view().deletions.is_empty());
    assert_eq!(rig.authority.state().posts(), posts, "no report traffic");
    assert_eq!(
        std::fs::read(rig.dir.join(STATE_FILE)).unwrap(),
        state_bytes
    );
    assert_eq!(holder_files(rig, ""), files);
}

