#[test]
fn h46_every_lease_counts_from_page_zero_receipt() {
    let (_dir, mut rig) = rig();
    rig.config.page_size = 1;
    rig.restart().unwrap();
    for id in [A, B] {
        rig.store.hold(PLAIN, id, true, 1);
        rig.authority.state().add_active(PLAIN, id);
    }
    // Page 1's transit is 20 s longer than page 0's: its own iat is 10 s
    // later and its own receipt 20 s later.
    let posts = rig.authority.state().posts();
    rig.authority
        .state()
        .before_post(posts + 2, |s| s.latency_ms = 20_000);
    use crate::clock::Clock;
    applied(rig.relist());
    let page0_received = rig.clock.mono_ms() - 20_000;
    // Keep the wall clock out of the decision.
    rig.clock.step_wall(-120_000);
    let now = rig.clock.mono_ms();
    rig.advance(page0_received + 899_000 - now);
    assert_eq!(plain(&rig, B), Ok(()));
    rig.advance(2_000);
    // Pairing page 1's own receipt with its own iat would serve until
    // page 0's receipt + 910 s.
    assert_eq!(plain(&rig, B), Err(Refusal::LeaseLapsed));
    assert_eq!(plain(&rig, A), Err(Refusal::LeaseLapsed));
}

#[test]
fn h48_a_rotation_retiring_every_old_kid_applies_before_the_new_epoch_list() {
    for attached in [true, false] {
        let (_dir, mut rig) = rig();
        rig.store.hold(PLAIN, A, true, 1);
        rig.authority.state().add_active(PLAIN, A);
        applied(rig.relist());
        let (old_kid, old_epoch, new_kid) = {
            let mut authority = rig.authority.state();
            let old_kid = authority.active_kid.clone();
            let old_epoch = authority.epoch.clone();
            let new = authority.issue_keyset(&[[0x77; 32]], &[old_kid.as_str()], None, attached);
            authority.use_key(&new[0]);
            authority.new_epoch();
            (old_kid, old_epoch, new[0].clone())
        };
        // The new-epoch list is refused (until S5), but its statement was
        // applied first and persisted.
        assert_eq!(
            failed(rig.relist()),
            crate::client::FetchFailure::UnexpectedEpoch
        );
        let pinned = rig.holder().pinned_keys().clone();
        assert!(pinned.keys.contains_key(&new_kid));
        assert!(!pinned.keys.contains_key(&old_kid));
        rig.restart().unwrap();
        assert!(!rig.holder().pinned_keys().keys.contains_key(&old_kid));

        // The old instance keeps signing with its key: refused.
        {
            let mut authority = rig.authority.state();
            authority.epoch = old_epoch.clone();
            authority.use_key(&old_kid);
            authority.attach_keyset = false;
        }
        assert_eq!(
            failed(rig.relist()),
            crate::client::FetchFailure::UnknownKid
        );
        let ack = rig.authority.state().sign_ack(&json!({"any": "claims"}));
        assert_eq!(rig.holder().verify_ack(&ack), Err("kid"));
    }
}

