/// Finding 5: a floor a list establishes is durable before any report can
/// run against it; if it cannot be made durable, the apply fails.
#[test]
fn f5_a_list_floor_that_cannot_be_made_durable_fails_the_apply_and_blocks_reports() {
    // In process: the apply fails, and no report runs on the older list.
    let mut w = world(false);
    let rig = &mut w.rig;
    rig.authority
        .state()
        .set_last_accepted(&w.b_holding, "incomplete");
    let before = std::fs::read(rig.dir.join(STATE_FILE)).unwrap();
    rig.io_faults.fail_writes(1);
    assert_eq!(rig.relist(), ListOutcome::ApplyFailed { step: "A1" });
    assert_eq!(std::fs::read(rig.dir.join(STATE_FILE)).unwrap(), before);
    let summary = rig.report().unwrap();
    assert_eq!((summary.derived, summary.sent), (0, 0));
    applied(rig.relist());
    assert_eq!(floor(rig, &w.b_obligation), Some(ReportState::Incomplete));
    rig.report().unwrap();
    assert!(!accepted_states(rig).contains(&"revoked".to_owned()));

    // After holder-state loss: the floor is in A1, so a later failed write
    // cannot leave the list applied with no floor.
    let mut w = world(false);
    let rig = &mut w.rig;
    rig.authority
        .state()
        .set_last_accepted(&w.b_holding, "incomplete");
    std::fs::remove_file(rig.dir.join(STATE_FILE)).unwrap();
    rig.data_root.view().marker = None;
    rig.restart().unwrap();
    rig.io_faults
        .plan(vec![Fault::Pass, Fault::Pass, Fault::BeforeRename]);
    applied(rig.relist());
    assert_eq!(floor(rig, &w.b_obligation), Some(ReportState::Incomplete));
    rig.io_faults.clear();
    rig.report().unwrap();
    assert!(accepted_states(rig).is_empty(), "nothing below the floor");
}

/// Finding 6: a crash after the last residual unit is deleted, or after the
/// reconfirmation was sent, still ends in a reconfirmed `complete`.
#[test]
fn f6_residual_reconfirmation_survives_a_restart() {
    for sent_before_crash in [false, true] {
        let mut w = world(false);
        let rig = &mut w.rig;
        rig.report().unwrap();
        rig.purge().unwrap();
        rig.report().unwrap();
        applied(rig.relist());
        rig.purger.add(PLAIN, B, 2);
        rig.purge().unwrap();
        assert_eq!(rig.purger.present_of(PLAIN, B), 0);
        if sent_before_crash {
            rig.authority.state().forced.push_back(Forced::Timeout);
            assert_eq!(rig.report().unwrap().sent, 1);
        }
        // Crash.
        rig.restart().unwrap();
        applied(rig.relist());
        if sent_before_crash {
            // No bytes remain and no scan exists yet: the durable report
            // waits; it is not invalidated.
            rig.advance(11_000);
            rig.report().unwrap();
            let waiting = pending(rig, &w.b_obligation).unwrap();
            assert_eq!(waiting.status, PendingStatus::Armed);
            assert!(rig.holder().state().obligations.uncertain.is_empty());
        }
        rig.purge().unwrap();
        rig.advance(11_000);
        let summary = rig.report().unwrap();
        assert_eq!(
            summary.converged, 1,
            "sent_before_crash={sent_before_crash}"
        );
        let channel = &rig.holder().state().obligations.channels[&w.b_obligation];
        assert!(!channel.reconfirm_pending);
        assert!(channel.pending.is_none());
    }
}

/// Finding 7: a `200` naming another obligation's uncertain key is never a
/// receipt; it goes through convergence, which refuses it.
#[test]
fn f7_a_response_naming_another_obligations_key_is_not_a_receipt() {
    let mut w = world(false);
    let rig = &mut w.rig;
    rig.store.hold(PLAIN, C, true, 1);
    rig.purger.add(PLAIN, C, 1);
    let c_obligation = {
        let mut authority = rig.authority.state();
        let holding = authority.add_active(PLAIN, C);
        authority.retire(&holding)
    };
    applied(rig.relist());
    // B's revoked report commits but its ack is lost; it becomes uncertain
    // and B's channel is held still.
    rig.authority.state().drop_acks = 1;
    rig.report().unwrap();
    let mut book = rig.holder().state().obligations.clone();
    let channel = book.channels.get_mut(&w.b_obligation).unwrap();
    let b_pending = channel.pending.take().unwrap();
    channel.halted = true;
    book.uncertain.insert(
        b_pending.key.clone(),
        Uncertain {
            before_resume: false,
            obligation_id: w.b_obligation.clone(),
            holding_id: w.b_holding.clone(),
            state: b_pending.body.state,
            epoch: b_pending.epoch.clone(),
            attempts: b_pending.attempts.clone(),
        },
    );
    rig.holder().writer.update_obligations(book).unwrap();
    // C's report is answered with B's genuine ack.
    let b_ack = rig.authority.state().current_acks[&w.b_obligation].clone();
    let answer = rig.authority.state().ack_answer(&b_ack, None);
    forced(rig, answer);
    rig.advance(11_000);
    let summary = rig.report().unwrap();
    assert_eq!((summary.sent, summary.receipts), (1, 0));
    assert!(codes(rig).contains(&"ack_unverifiable"));
    let state = rig.holder().state().obligations.clone();
    assert!(state.uncertain.contains_key(&b_pending.key), "B unresolved");
    assert_eq!(floor(rig, &w.b_obligation), None);
    assert!(pending(rig, &c_obligation).unwrap().live());
}

/// H.50: an uncertain higher attempt blocks a lower state until a verified
/// list with page-0 `iat > D = exp + 120 s` proves it was not committed.
#[test]
fn h50_a_lower_state_waits_until_page_zero_iat_passes_d() {
    let mut w = world(false);
    let rig = &mut w.rig;
    rig.report().unwrap();
    rig.purge().unwrap();
    // `complete` goes out and its answer is lost before the authority saw it.
    rig.authority.state().forced.push_back(Forced::Timeout);
    assert_eq!(rig.report().unwrap().sent, 1);
    // Unknown data appears: the claim is now `incomplete`, which is lower.
    rig.store.hold(PLAIN, X, true, 1);
    rig.purger.add(PLAIN, X, 1);
    rig.purge().unwrap();
    rig.advance(11_000);
    let summary = rig.report().unwrap();
    assert_eq!((summary.invalidated, summary.sent), (1, 0));
    let exp_s = {
        let book = &rig.holder().state().obligations;
        assert_eq!(book.uncertain.len(), 1);
        book.uncertain.values().next().unwrap().latest_exp_s()
    };
    // Page 0 at exactly D resolves nothing.
    use crate::clock::Clock;
    let now = rig.clock.wall_ms();
    rig.advance(u64::try_from((exp_s + 120) * 1000 - now).unwrap());
    applied(rig.holder().list_once());
    assert_eq!(rig.holder().state().obligations.uncertain.len(), 1);
    assert_eq!(rig.report().unwrap().sent, 0);
    // Past D (well before exp + 420 s): resolved, and the lower state goes.
    rig.advance(6_000);
    applied(rig.holder().list_once());
    assert!(rig.holder().state().obligations.uncertain.is_empty());
    assert_eq!(rig.report().unwrap().receipts, 1);
    assert_eq!(accepted_states(rig), ["revoked", "incomplete"]);
}

